    // Handle null source characters: if the class field `chars` is null, no token can be extracted.
    if (chars == null) {
        return null;
    }
    // Start index of the token
    final int start = pos;
    // Iterate through the character array until a terminator or the end of the array is reached.
    while (pos < chars.length) {
        char current = chars[pos];
        // If terminators are specified, check whether the current character matches any of them.
        boolean isTerminator = false;
        if (terminators != null) {
            for (char t : terminators) {
                if (t == current) {
                    isTerminator = true;
                    break;
                }
            }
        }
        // Stop on terminator or continue by advancing the position.
        if (isTerminator) {
            break;
        }
        pos++;
    }
    // Construct the token string from the characters between the start and current position.
    return new String(chars, start, pos - start);
}

