        }
        table.setRowSelectionInterval(row, row);
        Rectangle cellRect = table.getCellRect(row, 0, true);
        if (cellRect != null) {
            table.scrollRectToVisible(cellRect);
        }
        // Revalidate and repaint with a slight delay on the EDT
        java.awt.EventQueue.invokeLater(() -> pane.revalidate());
        java.awt.EventQueue.invokeLater(() -> table.repaint());
    } catch (Exception e) {
        // Swallow any unexpected issues to avoid breaking the caller
    }
}

